class FeedFrame {
  final bool reset;
  final List<MessageView> messages;
  final List<MessageRef>? order;
  final List<ToolResultsView> results;
  final List<FeedOp> ops;

  const FeedFrame({
    required this.reset,
    required this.messages,
    this.order,
    required this.results,
    required this.ops,
  });

  @override
  int get hashCode =>
      reset.hashCode ^
      const DeepCollectionEquality().hash(messages) ^
      const DeepCollectionEquality().hash(order) ^
      const DeepCollectionEquality().hash(results) ^
      const DeepCollectionEquality().hash(ops);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FeedFrame &&
          runtimeType == other.runtimeType &&
          reset == other.reset &&
          const DeepCollectionEquality().equals(messages, other.messages) &&
          const DeepCollectionEquality().equals(order, other.order) &&
          const DeepCollectionEquality().equals(results, other.results) &&
          const DeepCollectionEquality().equals(ops, other.ops);
}

/// A row and its feed key. `keyed` is false for a row Dart drew without a
/// key; its feed key is a stand-in.
class FeedItem {
  final String key;
  final bool keyed;
  final FeedRow row;

  const FeedItem({required this.key, required this.keyed, required this.row});

  @override
  int get hashCode => key.hashCode ^ keyed.hashCode ^ row.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FeedItem &&
          runtimeType == other.runtimeType &&
          key == other.key &&
          keyed == other.keyed &&
          row == other.row;
}

@freezed
sealed class FeedOp with _$FeedOp {
  const FeedOp._();

  /// Inserts or replaces `item` after `after` (`None`: first).
  const factory FeedOp.upsert({String? after, required FeedItem item}) =
      FeedOp_Upsert;
  const factory FeedOp.remove({required String key}) = FeedOp_Remove;
}

@freezed
sealed class FeedRow with _$FeedRow {
  const FeedRow._();

  const factory FeedRow.message({
    required int uid,
    ResultsRef? results,
    required bool streamingSpinner,
    required bool parts,
  }) = FeedRow_Message;
  const factory FeedRow.run({
    required String runKey,
    required List<StepRef> steps,
    required int shownFrom,
    required bool expanded,
    required ResultsRef results,
    String? anchorMessageId,
  }) = FeedRow_Run;
  const factory FeedRow.steps({
    required String turnKey,
    required List<StepCountView> counts,
    required bool expanded,
    TimerView? timer,
  }) = FeedRow_Steps;
  const factory FeedRow.timer({String? turnKey, TimerView? timer}) =
      FeedRow_Timer;
  const factory FeedRow.turnFooter({required String turnKey}) =
      FeedRow_TurnFooter;
  const factory FeedRow.responseActions({
    required int uid,
    required String turnKey,
    required String atMessageId,
  }) = FeedRow_ResponseActions;
}

/// A presented message's place in the transcript, with what turn feedback
/// reads of it whether or not a row materializes it.
class MessageRef {
  final int uid;
  final String id;
  final ChatRole? role;
  final bool continuesTurn;

  /// `hasRenderableContent`.
  final bool renderable;

  const MessageRef({
    required this.uid,
    required this.id,
    this.role,
    required this.continuesTurn,
    required this.renderable,
  });

  @override
  int get hashCode =>
      uid.hashCode ^
      id.hashCode ^
      role.hashCode ^
      continuesTurn.hashCode ^
      renderable.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MessageRef &&
          runtimeType == other.runtimeType &&
          uid == other.uid &&
          id == other.id &&
          role == other.role &&
          continuesTurn == other.continuesTurn &&
          renderable == other.renderable;
}

enum MessageStatus { streaming, complete, failed, cancelled }

/// A presented message (`ChatMessage` of the selected chat). An entry never changes: a new
/// version of a message is a new `uid`.
class MessageView {
  final int uid;
  final String id;
  final ChatRole? role;
  final MessageStatus status;
  final String text;
  final WatcherFiredView? watcherFired;
  final List<AttachmentView> attachments;
  final int? occurredAtMs;
  final bool continuesTurn;
  final List<PartView> parts;

  const MessageView({
    required this.uid,
    required this.id,
    this.role,
    required this.status,
    required this.text,
    this.watcherFired,
    required this.attachments,
    this.occurredAtMs,
    required this.continuesTurn,
    required this.parts,
  });

  @override
  int get hashCode =>
      uid.hashCode ^
      id.hashCode ^
      role.hashCode ^
      status.hashCode ^
      text.hashCode ^
      watcherFired.hashCode ^
      const DeepCollectionEquality().hash(attachments) ^
      occurredAtMs.hashCode ^
      continuesTurn.hashCode ^
      const DeepCollectionEquality().hash(parts);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MessageView &&
          runtimeType == other.runtimeType &&
          uid == other.uid &&
          id == other.id &&
          role == other.role &&
          status == other.status &&
          text == other.text &&
          watcherFired == other.watcherFired &&
          const DeepCollectionEquality().equals(
            attachments,
            other.attachments,
          ) &&
          occurredAtMs == other.occurredAtMs &&
          continuesTurn == other.continuesTurn &&
          const DeepCollectionEquality().equals(parts, other.parts);
}

